package com.hiliving.content.news;import java.time.Instant;public record NewsResponse(Long id,String title,String slug,NewsCategory category,String content,String thumbnailUrl,boolean published,Instant publishedAt,int sortOrder,Instant createdAt,Instant updatedAt){static NewsResponse from(NewsEntity n,String content){return new NewsResponse(n.getId(),n.getTitle(),n.getSlug(),n.getCategory(),content,n.getThumbnailUrl(),n.isPublished(),n.getPublishedAt(),n.getDisplayOrder(),n.getCreatedAt(),n.getUpdatedAt());}}
